    mtg3_seller_carry_back = CASE WHEN LOWER(d.seller_name_plaintiff_1) = LOWER(d.mtg3_lender_last_name) OR LOWER(d.seller_name_plaintiff_1) = LOWER(RTRIM(LTRIM(d.mtg3_lender_last_name || ' ' || d.mtg3_lender_first_name))) OR LOWER(RTRIM(LTRIM(s.last_company_name || ' ' || s.first_name))) = LOWER(RTRIM(LTRIM(d.mtg3_lender_last_name || ' ' || d.mtg3_lender_first_name))) OR LOWER(d.seller_name_plaintiff_2) = LOWER(d.mtg3_lender_last_name) OR LOWER(d.seller_name_plaintiff_2) = LOWER(RTRIM(LTRIM(d.mtg3_lender_last_name || ' ' || d.mtg3_lender_first_name))) OR LOWER(RTRIM(LTRIM(s2.last_company_name || ' ' || s2.first_name))) = LOWER(RTRIM(LTRIM(d.mtg3_lender_last_name || ' ' || d.mtg3_lender_first_name))) THEN 'Y' ELSE NULL END,
    mtg4_seller_carry_back = CASE WHEN LOWER(d.seller_name_plaintiff_1) = LOWER(d.mtg4_lender_last_name) OR LOWER(d.seller_name_plaintiff_1) = LOWER(RTRIM(LTRIM(d.mtg4_lender_last_name || ' ' || d.mtg4_lender_first_name))) OR LOWER(RTRIM(LTRIM(s.last_company_name || ' ' || s.first_name))) = LOWER(RTRIM(LTRIM(d.mtg4_lender_last_name || ' ' || d.mtg4_lender_first_name))) OR LOWER(d.seller_name_plaintiff_2) = LOWER(d.mtg4_lender_last_name) OR LOWER(d.seller_name_plaintiff_2) = LOWER(RTRIM(LTRIM(d.mtg4_lender_last_name || ' ' || d.mtg4_lender_first_name))) OR LOWER(RTRIM(LTRIM(s2.last_company_name || ' ' || s2.first_name))) = LOWER(RTRIM(LTRIM(d.mtg4_lender_last_name || ' ' || d.mtg4_lender_first_name))) THEN 'Y' ELSE NULL END,
